function formatAdmissionCreatedAt(value) {
  const date = new Date(value)
  if (!value || Number.isNaN(date.getTime())) return 'Creation time unavailable'
  return new Intl.DateTimeFormat('en-KE', { dateStyle: 'medium', timeStyle: 'short', timeZone: 'Africa/Nairobi' }).format(date)
}

