  const category=item=>item.staffType||(/teacher|headteacher/i.test(item.role||'')?'Teaching':'Support');const teaching=staff.filter(item=>category(item)==='Teaching'),support=staff.filter(item=>category(item)==='Support')
  const submit=async event=>{event.preventDefault();const form=new FormData(event.currentTarget);setSaving(true);try{const saved=await createStaff({fullName:String(form.get('fullName')||'').trim(),staffType,role:String(form.get('role')||''),phone:String(form.get('phone')||'').trim(),email:String(form.get('email')||'').trim(),employmentStatus:'Active'});setStaff(items=>[...items,saved]);setStatus(`${saved.fullName} was added to ${saved.staffType.toLowerCase()} staff.`);setFormOpen(false);event.currentTarget.reset()}catch(error){setStatus(error.message)}finally{setSaving(false)}}
