  const print=()=>{const rows=staff.map((item,index)=>`<tr><td>${index+1}</td><td>${item.fullName}</td><td>${category(item)}</td><td>${item.role}</td><td>${item.phone||'—'}</td><td>${item.employmentStatus||'Active'}</td></tr>`).join('')||'<tr><td colspan="6">No staff profiles recorded.</td></tr>';const page=window.open('','_blank');if(!page)return setStatus('Allow pop-ups to open the staff register.');page.document.write(`<!doctype html><html><head><title>St. Dorothy School staff register</title><style>body{font-family:Arial;color:#173662;padding:28px}header{text-align:center;border-bottom:2px solid #d69b16;padding-bottom:12px}h1{font-size:22px;margin:0 0 6px}h2{font-size:16px;margin:20px 0 10px}small{color:#60748a}table{width:100%;border-collapse:collapse;font-size:11px}th{background:#173f72;color:#fff;text-align:left;padding:8px}td{padding:8px;border-bottom:1px solid #dce6ef}tr:nth-child(even){background:#f5f9fd}@media print{body{padding:0}}</style></head><body><header><h1>ST. DOROTHY'S SCHOOL MASSIMO</h1><small>P.O. Box 36-60607, Mikinduri, Meru, Kenya · +254 722 841 569</small></header><h2>SCHOOL STAFF REGISTER</h2><small>Teaching staff: ${teaching.length} · Support staff: ${support.length} · Generated ${new Date().toLocaleString('en-KE')}</small><table><thead><tr><th>No.</th><th>Name</th><th>Category</th><th>Role</th><th>Phone</th><th>Status</th></tr></thead><tbody>${rows}</tbody></table></body></html>`);page.document.close();page.focus();setTimeout(()=>page.print(),250)}
