  return <main className="system-admin-shell admin-workspace"><header><div className="system-admin-brand"><ShieldCheck size={24}/><div><strong>St. Dorothy School</strong><span>System administration</span></div></div><div><LiveDateTime/><button onClick={onExit}>Sign out</button></div></header><div className="admin-layout"><aside className="admin-sidebar"><p>ADMIN MENU</p>{items.map(([label,Icon])=><button key={label} className={active===label?'active':''} onClick={()=>setActive(label)}><Icon size={18}/>{label}</button>)}</aside><section className="admin-content"><div className="admin-content-heading"><div><p className="eyebrow">System administration</p><h2>{active}</h2></div></div>{content}</section></div>{status&&<button className="parent-toast" onClick={()=>setStatus('')}><ClipboardCheck size={17}/><span>{status}</span><b>×</b></button>}</main>
